              } else if (a1b1 == 0) {
                  entry = T4_T6_Tables.V0;
              } else if (a1b1 == 1) {
                  entry = T4_T6_Tables.VR1;
              } else if (a1b1 == 2) {
                  entry = T4_T6_Tables.VR2;
              } else {
