package org.apache.commons.imaging.palette;

enum ColorComponent {
    ALPHA(24),
    RED(16),
    GREEN(8),
    BLUE(0);

    private final int shift;

    ColorComponent(final int shift) {
        this.shift = shift;
    }

    public int argbComponent(final int argb) {
        return (argb >> shift) & 0xff;
    }
}

