    @Test
    public void testAlphaComponent() {
        int argb = 0x80FFFFFF; // 50% transparent white
        int expectedAlpha = 0x80;
        assertEquals(expectedAlpha, ColorComponent.ALPHA.argbComponent(argb));
    }

